// Renders pack.json as lib/config/pack.g.dart.

/// Palette roles in output order; pack.json must define exactly these.
const paletteRoles = [
  'primary',
  'primaryDeep',
  'ink',
  'paper',
  'accent',
  'alert',
  'shade',
  'highlight',
];

const _header =
    '// GENERATED by tool/apply_pack.dart from pack/pack.json. Do not edit.\n'
    "import 'dart:ui';\n";

/// The generated Dart source, already in `dart format` layout.
String packDart(Map<String, dynamic> pack) {
  final palette = pack['palette'];
  if (palette is! Map<String, dynamic>) {
    throw const FormatException('pack.json: "palette" must be an object');
  }
  final extra = palette.keys.where((k) => !paletteRoles.contains(k));
  if (extra.isNotEmpty) {
    throw FormatException('pack.json: unknown palette roles $extra');
  }
  final colors = [
    for (final role in paletteRoles)
      '  static const $role = Color(0xFF${hexColor(palette, role)});',
  ];
  return [
    _header,
    _const('packAppName', _string(pack, 'appName')),
    _const('packTagline', _string(pack, 'tagline')),
    _const('packEventLine', _string(pack, 'eventLine')),
    'final packEventEnd = ${_dateTime(_string(pack, 'eventEnd'))};',
    _const('packDefaultSiteId', _string(pack, 'defaultSiteId')),
    '',
    'abstract final class AppColors {',
    ...colors,
    '}',
    '',
  ].join('\n');
}

/// `RRGGBB` (upper case) of palette[role], which must be `#RRGGBB`.
String hexColor(Map<String, dynamic> palette, String role) {
  final v = palette[role];
  if (v is! String || !RegExp(r'^#[0-9A-Fa-f]{6}$').hasMatch(v)) {
    throw FormatException('pack.json: palette.$role must be "#RRGGBB"');
  }
  return v.substring(1).toUpperCase();
}

String _string(Map<String, dynamic> pack, String key) {
  final v = pack[key];
  if (v is! String || v.isEmpty) {
    throw FormatException('pack.json: "$key" must be a non-empty string');
  }
  return v;
}

/// Mirrors dart format: a declaration over 80 columns breaks after `=`.
String _const(String name, String value) {
  final literal = dartString(value);
  final line = 'const $name = $literal;';
  return line.length <= 80 ? line : 'const $name =\n    $literal;';
}

/// Single-quoted Dart literal; escapes keep `$` and quotes literal.
String dartString(String s) {
  final b = StringBuffer("'");
  for (final c in s.runes) {
    b.write(switch (c) {
      0x5C => r'\\',
      0x27 => r"\'",
      0x24 => r'\$',
      0x0A => r'\n',
      0x0D => r'\r',
      0x09 => r'\t',
      < 0x20 => '\\u{${c.toRadixString(16)}}',
      _ => String.fromCharCode(c),
    });
  }
  b.write("'");
  return b.toString();
}

/// Always six fields; milliseconds only when non-zero.
String _dateTime(String iso) {
  final DateTime t;
  try {
    t = DateTime.parse(iso).toUtc();
  } on FormatException {
    throw FormatException('pack.json: eventEnd "$iso" is not ISO 8601');
  }
  final fields = [t.year, t.month, t.day, t.hour, t.minute, t.second];
  if (t.millisecond != 0) fields.add(t.millisecond);
  return 'DateTime.utc(${fields.join(', ')})';
}
